  "critique": [
    {
      "design": "r1A",
      "good": "The keys remain intact, headers are clear, and the shared row heights keep translations associated. English and Arabic have relatively comfortable line breaks.",
      "problems": "Japanese leaves a single character on the second line of the first translation and on the fourth line of the email message. Chinese and Arabic also make the shipping row three lines tall.",
      "cause": "The 120px Japanese column is just too narrow for cleaner breaks in those cells. The 94px Chinese and 95px Arabic columns constrain the longer shipping translations."
    },
    {
      "design": "r1B",
      "good": "The 130px Japanese column keeps the first two translations on one line and reduces the email message to three lines. Keys and headers remain intact.",
      "problems": "Arabic becomes noticeably fragmented, including two-line versions of short phrases and a four-line email message. The wider Japanese column therefore does not reduce the height of the longest row.",
      "cause": "The extra Japanese width comes from reducing Arabic to 89px and Chinese to 90px; Arabic has only 68px of text space."
    },
    {
      "design": "r1C",
      "good": "Arabic reads more comfortably, with the first two translations on one line and the email message in three. The keys remain intact and the language columns retain a clear hierarchy.",
      "problems": "The Japanese email message occupies four lines with awkward breaks, and the first Japanese translation wraps. The extra English width does not visibly improve the row heights.",
      "cause": "Japanese has only 108px, while English receives 130px and still wraps the same phrases as in the other designs."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "arabic-priority",
      "widths": [227, 125, 94, 108, 107],
      "change": "Build on r1C by moving 5px from English and 2px from Chinese to Arabic. Test whether the wider Arabic column improves the shipping or search breaks while retaining readable English."
    },
    {
      "name": "chinese-priority",
      "widths": [227, 125, 101, 108, 100],
      "change": "Move 5px from English to Chinese in r1C. Test whether the extra Chinese text space improves the shipping row while preserving the more comfortable Arabic width."
    },
    {
      "name": "balanced-japanese",
      "widths": [227, 125, 90, 119, 100],
      "change": "Combine r1A's near-120px Japanese width with r1C's 100px Arabic width, using a narrower Chinese column. Test whether this gives Japanese and Arabic a better balance without making Chinese wraps too ragged."
    }
  ]
